  echo -e "    ${CYAN}bash $0 update${NC}      - $(t app.sub2api.summary.cmd_update)"
  echo -e "    ${CYAN}bash $0 backup${NC}      - $(t app.sub2api.summary.cmd_backup)"
  echo -e "    ${CYAN}bash $0 uninstall${NC}   - $(t app.sub2api.summary.cmd_uninstall)"
