  echo -e "    ${CYAN}journalctl -u ${SERVICE_NAME} -f${NC}      $(t app.sub2api.summary.systemd_logs)"
  echo -e "    ${CYAN}systemctl restart ${SERVICE_NAME}${NC}     $(t app.sub2api.summary.systemd_restart)"
